        "content": "import { describe, expect, test } from \"bun:test\";\nimport { classifyLine, extractKey, validateYaml } from \"./yaml-validator\";\nimport { LineType } from \"./yaml-validator-types\";\n\ndescribe(\"classifyLine\", () => {\n  test(\"blank lines return Blank\", () => {\n    expect(classifyLine(\"\")).toBe(LineType.Blank);\n    expect(classifyLine(\"   \")).toBe(LineType.Blank);\n    expect(classifyLine(\"  \\t  \")).toBe(LineType.Blank);\n  });\n\n  test(\"comment lines return Comment\", () => {\n    expect(classifyLine(\"# this is a comment\")).toBe(LineType.Comment);\n    expect(classifyLine(\"  # indented comment\")).toBe(LineType.Comment);\n    expect(classifyLine(\"#\")).toBe(LineType.Comment);\n  });\n\n  test(\"document start marker returns DocumentStart\", () => {\n    expect(classifyLine(\"---\")).toBe(LineType.DocumentStart);\n    expect(classifyLine(\"--- \")).toBe(LineType.DocumentStart);\n    expect(classifyLine(\"---  \")).toBe(LineType.DocumentStart);\n  });\n\n  test(\"document end marker returns DocumentEnd\", () => {\n    expect(classifyLine(\"...\")).toBe(LineType.DocumentEnd);\n    expect(classifyLine(\"... \")).toBe(LineType.DocumentEnd);\n  });\n\n  test(\"mapping pairs return MappingPair\", () => {\n    expect(classifyLine(\"key: value\")).toBe(LineType.MappingPair);\n    expect(classifyLine(\"name: John\")).toBe(LineType.MappingPair);\n    expect(classifyLine(\"  nested: true\")).toBe(LineType.MappingPair);\n    expect(classifyLine(\"key:\")).toBe(LineType.MappingPair);\n    expect(classifyLine(\"key: \")).toBe(LineType.MappingPair);\n  });\n\n  test(\"sequence items return SequenceItem\", () => {\n    expect(classifyLine(\"- item\")).toBe(LineType.SequenceItem);\n    expect(classifyLine(\"  - nested item\")).toBe(LineType.SequenceItem);\n    expect(classifyLine(\"-\")).toBe(LineType.SequenceItem);\n    expect(classifyLine(\"- \")).toBe(LineType.SequenceItem);\n  });\n\n  test(\"quoted strings preserving colons classify correctly\", () => {\n    expect(classifyLine('key: \"value:with:colons\"')).toBe(\n      LineType.MappingPair,\n    );\n    expect(classifyLine(\"key: 'value:with:colons'\")).toBe(\n      LineType.MappingPair,\n    );\n    expect(classifyLine('\"quoted:key\": value')).toBe(LineType.MappingPair);\n  });\n\n  test(\"directives return Directive\", () => {\n    expect(classifyLine(\"%YAML 1.2\")).toBe(LineType.Directive);\n    expect(classifyLine(\"%TAG !yaml! tag:yaml.org,2002:\")).toBe(\n      LineType.Directive,\n    );\n  });\n\n  test(\"scalar continuation for unclassifiable content\", () => {\n    expect(classifyLine(\"just some text\")).toBe(LineType.ScalarContinuation);\n    expect(classifyLine(\"no-colon-separator\")).toBe(\n      LineType.ScalarContinuation,\n    );\n  });\n});\n\ndescribe(\"extractKey\", () => {\n  test(\"simple keys extracted from mapping pairs\", () => {\n    expect(extractKey(\"name: John\")).toBe(\"name\");\n    expect(extractKey(\"age: 30\")).toBe(\"age\");\n    expect(extractKey(\"key: value\")).toBe(\"key\");\n  });\n\n  test(\"quoted keys have quotes stripped\", () => {\n    expect(extractKey('\"quoted key\": value')).toBe(\"quoted key\");\n    expect(extractKey(\"'single quoted': value\")).toBe(\"single quoted\");\n  });\n\n  test(\"colons inside quoted strings do not split key\", () => {\n    expect(extractKey('\"key:with:colons\": value')).toBe(\"key:with:colons\");\n    expect(extractKey(\"'key:colon': value\")).toBe(\"key:colon\");\n  });\n\n  test(\"returns null when no colon separator is found\", () => {\n    expect(extractKey(\"no colon here\")).toBeNull();\n    expect(extractKey(\"- list item\")).toBeNull();\n    expect(extractKey(\"\")).toBeNull();\n  });\n\n  test(\"key with indentation\", () => {\n    expect(extractKey(\"  nested_key: value\")).toBe(\"nested_key\");\n    expect(extractKey(\"    deep_key: value\")).toBe(\"deep_key\");\n  });\n\n  test(\"key at end of line with no value\", () => {\n    expect(extractKey(\"key:\")).toBe(\"key\");\n    expect(extractKey(\"parent: \")).toBe(\"parent\");\n  });\n\n  test(\"colon without space after it is not a separator\", () => {\n    expect(extractKey(\"http://example.com\")).toBeNull();\n    expect(extractKey(\"host:port\")).toBeNull();\n  });\n});\n\ndescribe(\"validateYaml\", () => {\n  describe(\"valid simple YAML documents\", () => {\n    test(\"simple key-value pairs\", () => {\n      const yaml = \"name: John\\nage: 30\\ncity: NYC\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n      expect(result.documentCount).toBe(1);\n    });\n\n    test(\"empty content is valid\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"only comments is valid\", () => {\n      const yaml = \"# This is a comment\\n# Another comment\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"only blank lines is valid\", () => {\n      const yaml = \"\\n\\n\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"mixed scalar types\", () => {\n      const yaml = [\n        \"string_val: hello\",\n        \"number_val: 42\",\n        \"float_val: 3.14\",\n        \"bool_true: true\",\n        \"bool_false: false\",\n        \"null_val: null\",\n        \"tilde_null: ~\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"sequences (list items)\", () => {\n      const yaml = [\"fruits:\", \"  - apple\", \"  - banana\", \"  - cherry\"].join(\n        \"\\n\",\n      );\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"nested mappings\", () => {\n      const yaml = [\n        \"server:\",\n        \"  host: localhost\",\n        \"  port: 8080\",\n        \"  ssl:\",\n        \"    enabled: true\",\n        \"    cert: /path/to/cert\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"quoted strings\", () => {\n      const yaml = [\n        'name: \"John Doe\"',\n        \"title: 'Senior Developer'\",\n        'message: \"Hello, World!\"',\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"colons inside quoted strings\", () => {\n      const yaml = [\n        'url: \"http://example.com:8080\"',\n        \"time: '12:30:00'\",\n        'note: \"key: value\"',\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"inline comments after values\", () => {\n      const yaml = [\n        \"name: John # first name\",\n        \"age: 30 # years old\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"invalid indentation\", () => {\n    test(\"inconsistent indentation levels\", () => {\n      const yaml = [\n        \"parent:\",\n        \"  child1: val\",\n        \"   child2: val\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      const indentError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"indentation\"),\n      );\n      expect(indentError).toBeDefined();\n    });\n\n    test(\"dedent to non-matching level\", () => {\n      const yaml = [\n        \"a:\",\n        \"  b:\",\n        \"    c: 1\",\n        \" d: 2\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const indentError = result.errors.find((e) =>\n        e.message.includes(\"Inconsistent indentation\"),\n      );\n      expect(indentError).toBeDefined();\n      expect(indentError!.line).toBe(4);\n    });\n  });\n\n  describe(\"tab characters\", () => {\n    test(\"tab used for indentation produces error\", () => {\n      const yaml = \"parent:\\n\\tchild: value\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const tabError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"tab\"),\n      );\n      expect(tabError).toBeDefined();\n      expect(tabError!.line).toBe(2);\n    });\n\n    test(\"multiple tab errors accumulated\", () => {\n      const yaml = \"a:\\n\\tb: 1\\n\\tc: 2\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const tabErrors = result.errors.filter((e) =>\n        e.message.toLowerCase().includes(\"tab\"),\n      );\n      expect(tabErrors.length).toBeGreaterThanOrEqual(2);\n    });\n  });\n\n  describe(\"unclosed quoted strings\", () => {\n    test(\"unclosed double quote at end of file\", () => {\n      const yaml = 'name: \"unclosed string';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const quoteError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"unclosed\"),\n      );\n      expect(quoteError).toBeDefined();\n      expect(quoteError!.line).toBe(1);\n    });\n\n    test(\"unclosed single quote at end of file\", () => {\n      const yaml = \"name: 'unclosed string\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const quoteError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"unclosed\"),\n      );\n      expect(quoteError).toBeDefined();\n    });\n\n    test(\"unclosed quote references the opening line\", () => {\n      const yaml = [\n        \"key1: valid\",\n        'key2: \"this never closes',\n        \"key3: also valid\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const quoteError = result.errors.find((e) =>\n        e.message.includes(\"Unclosed\"),\n      );\n      expect(quoteError).toBeDefined();\n      expect(quoteError!.line).toBe(2);\n    });\n  });\n\n  describe(\"duplicate keys\", () => {\n    test(\"duplicate keys at same level produce error\", () => {\n      const yaml = [\"name: John\", \"age: 30\", \"name: Jane\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const dupError = result.errors.find((e) =>\n        e.message.includes(\"Duplicate key\"),\n      );\n      expect(dupError).toBeDefined();\n      expect(dupError!.message).toContain(\"name\");\n    });\n\n    test(\"same key at different nesting levels is valid\", () => {\n      const yaml = [\n        \"parent:\",\n        \"  name: child_name\",\n        \"name: top_level_name\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"duplicate key error references both lines\", () => {\n      const yaml = [\"host: alpha\", \"port: 80\", \"host: beta\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const dupError = result.errors.find((e) =>\n        e.message.includes(\"Duplicate key\"),\n      );\n      expect(dupError).toBeDefined();\n      expect(dupError!.line).toBe(3);\n      expect(dupError!.message).toContain(\"line 1\");\n    });\n  });\n\n  describe(\"multi-document YAML\", () => {\n    test(\"documents separated by --- are valid\", () => {\n      const yaml = [\n        \"---\",\n        \"name: doc1\",\n        \"---\",\n        \"name: doc2\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.documentCount).toBe(2);\n    });\n\n    test(\"document end marker (...) handled\", () => {\n      const yaml = [\n        \"---\",\n        \"name: doc1\",\n        \"...\",\n        \"---\",\n        \"name: doc2\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.documentCount).toBe(2);\n    });\n\n    test(\"content after ... without --- is invalid\", () => {\n      const yaml = [\n        \"name: doc1\",\n        \"...\",\n        \"name: orphan\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      const afterEndError = result.errors.find((e) =>\n        e.message.includes(\"document end marker\"),\n      );\n      expect(afterEndError).toBeDefined();\n    });\n\n    test(\"duplicate keys reset across document boundaries\", () => {\n      const yaml = [\n        \"---\",\n        \"name: doc1\",\n        \"---\",\n        \"name: doc2\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"single document without explicit --- counts as 1\", () => {\n      const yaml = \"key: value\";\n      const result = validateYaml(yaml);\n      expect(result.documentCount).toBe(1);\n    });\n  });\n\n  describe(\"block scalars\", () => {\n    test(\"literal block scalar (|) content is not flagged\", () => {\n      const yaml = [\n        \"description: |\",\n        \"  This is a multi-line\",\n        \"  literal block scalar.\",\n        \"name: after\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"folded block scalar (>) content is not flagged\", () => {\n      const yaml = [\n        \"summary: >\",\n        \"  This is a folded\",\n        \"  block scalar value.\",\n        \"name: next\",\n      ].join(\"\\n\"