rors:\", r.errors.length);\n\nr = validateYaml(\"# just a comment\");\nconsole.log(\"comment only:\", r.valid, \"docs:\", r.documentCount);\n\nr = validateYaml(\"\");\nconsole.log(\"empty:\", r.valid, \"docs:\", r.documentCount);\n\nr = validateYaml(\"---\\nkey: value\\n---\\nother: value\");\nconsole.log(\"multi-doc:\", r.valid, \"docs:\", r.documentCount);\n\nr = validateYaml(\"key: value\\nkey: other\");\nconsole.log(\"duplicate key:\", r.valid, \"errors:\", r.errors.length, r.errors[0]?.message);\n\nr = validateYaml(\"\\tkey: value\");\nconsole.log(\"tab indent:\", r.valid, \"errors:\", r.errors.length, r.errors[0]?.message);\n\nr = validateYaml(\"key: \\\"unclosed string\");\nconsole.log(\"unclosed quote:\", r.valid, \"errors:\", r.errors.length, r.errors[0]?.message);\n\nr = validateYaml(\"a:\\n  b: 1\\n  c: 2\\n   d: 3\");\nconsole.log(\"inconsistent indent:\", r.valid, \"errors:\", r.errors.length, r.errors[0]?.message);\n\nr = validateYaml(\"items:\\n  - name: a\\n    value: 1\\n  - name: b\\n    value: 2\");\nconsole.log(\"nested seq (valid):\", r.valid);\n\nr = validateYaml(\"...\\ncontent: here\");\nconsole.log(\"content after doc end:\", r.valid, \"errors:\", r.errors.length, r.errors[0]?.message);\n\nr = validateYaml(\"key: |\\n  block scalar\\n  content here\\nnext: value\");\nconsole.log(\"block scalar:\", r.valid, \"docs:\", r.documentCount);\n'\n",
