    "bun -e \"\nimport { classifyLine, validateYaml, extractKey } from './src/yaml-validator';\nimport { LineType } from './src/yaml-validator-types';\n\nlet pass = 0;\nlet fail = 0;\nfunction assert(name, actual, expected) {\n  if (actual === expected) { pass++; }\n  else { fail++; console.log('FAIL:', name, 'got', actual, 'expected', expected); }\n}\n\n// classifyLine tests\nassert('blank', classifyLine(''), LineType.Blank);\nassert('blank spaces', classifyLine('   '), LineType.Blank);\nassert('comment', classifyLine('# hi'), LineType.Comment);\nassert('indented comment', classifyLine('  # hi'), LineType.Comment);\nassert('doc start', classifyLine('---'), LineType.DocumentStart);\nassert('doc start comment', classifyLine('--- # hi'), LineType.DocumentStart);\nassert('doc end', classifyLine('...'), LineType.DocumentEnd);\nassert('directive', classifyLine('%YAML 1.2'), LineType.Directive);\nassert('seq item', classifyLine('- item'), LineType.SequenceItem);\nassert('seq indented', classifyLine('  - item'), LineType.SequenceItem);\nassert('bare dash', classifyLine('-'), LineType.SequenceItem);\nassert('mapping', classifyLine('key: val'), LineType.MappingPair);\nassert('mapping null', classifyLine('key:'), LineType.MappingPair);\nassert('mapping indented', classifyLine('  key: val'), LineType.MappingPair);\nassert('scalar', classifyLine('just text'), LineType.ScalarContinuation);\nassert('url', classifyLine('http://example.com'), LineType.ScalarContinuation);\nassert('not doc start', classifyLine('---abc'), LineType.ScalarContinuation);\n\n// extractKey tests\nassert('key simple', extractKey('key: val'), 'key');\nassert('key quoted', extractKey('\\\"my key\\\": val'), 'my key');\nassert('key null val', extractKey('key:'), 'key');\nassert('key indented', extractKey('  key: val'), 'key');\n\n// validateYaml - valid cases\nlet r;\nr = validateYaml('key: value');\nassert('simple valid', r.valid, true);\nassert('simple docs', r.documentCount, 1);\n\nr = validateYaml('# comment only');\nassert('comment only valid', r.valid, true);\nassert('comment docs', r.documentCount, 0);\n\nr = validateYaml('');\nassert('empty valid', r.valid, true);\nassert('empty docs', r.documentCount, 0);\n\nr = validateYaml('---\\na: 1\\n---\\nb: 2');\nassert('multi-doc valid', r.valid, true);\nassert('multi-doc count', r.documentCount, 2);\n\nr = validateYaml('a:\\n  b: 1\\n  c: 2');\nassert('nested valid', r.valid, true);\n\nr = validateYaml('items:\\n  - name: a\\n    val: 1\\n  - name: b\\n    val: 2');\nassert('seq nested valid', r.valid, true);\n\nr = validateYaml('key: \\\"hello world\\\"');\nassert('double quoted valid', r.valid, true);\n\nr = validateYaml('key: \\\"value with # hash\\\"');\nassert('hash in quotes valid', r.valid, true);\n\nr = validateYaml('description: |\\n  block scalar\\n  content\\nnext: val');\nassert('block scalar valid', r.valid, true);\n\n// validateYaml - invalid cases\nr = validateYaml('a: 1\\na: 2');\nassert('dup key invalid', r.valid, false);\nassert('dup key msg', r.errors[0]?.message.includes('Duplicate key'), true);\n\nr = validateYaml('\\tkey: val');\nassert('tab invalid', r.valid, false);\nassert('tab msg', r.errors[0]?.message.includes('Tab'), true);\n\nr = validateYaml('key: \\\"unclosed');\nassert('unclosed quote invalid', r.valid, false);\nassert('unclosed msg', r.errors[0]?.message.includes('Unclosed'), true);\n\nr = validateYaml('a:\\n  b: 1\\n    c: 2\\n   d: 3');\nassert('inconsistent indent', r.valid, false);\nassert('indent msg', r.errors[0]?.message.includes('Inconsistent'), true);\n\nr = validateYaml('...\\ncontent: here');\nassert('after doc end', r.valid, false);\n\n// Multi-error accumulation\nr = validateYaml('a: 1\\na: 2\\nb: 3\\nb: 4');\nassert('multi errors count', r.errors.length, 2);\n\n// 1-based line numbers\nr = validateYaml('a: 1\\nb: 2\\nb: 3');\nassert('dup line number', r.errors[0]?.line, 3);\n\n// Document separator resets keys\nr = validateYaml('---\\nkey: 1\\n---\\nkey: 2');\nassert('key