import { validateYaml } from "./src/yaml-validator";

// Test: a:\n  b: 1\n  c: 2\n   d: 3
// Indent levels: 0, 2, 2, 3
// d at indent 3 is inconsistent (not matching 0 or 2)
let r = validateYaml("a:\n  b: 1\n  c: 2\n   d: 3");
console.log("result:", JSON.stringify(r, null, 2));

// The issue: indent 3 is > top (2), so it gets pushed as a deeper level.
// It should be detected as inconsistent because 3 is odd.
// Actually the validator tracks indent levels as absolute positions, 
// not relative. So 3 is valid as "deeper than 2".
// The "inconsistent" case is when we DEDENT to a level not on the stack.

// Better test: indent then come back to a level that was never on stack
r = validateYaml("a:\n  b: 1\n    c: 2\n   d: 3");
console.log("result2:", JSON.stringify(r, null, 2));

// Here: 0, 2, 4, 3. Dedent from 4 to 3. 3 is not on stack [0, 2, 4].
// After popping 4, top is 2. 3 > 2 but not == 2. 
// The loop: top=4, 4>3, pop. top=2, 2<3, break. found=false.
'

